const { convert } = require('number-to-words-indian');

function formatIndianCurrency(amount) {
    // 1. Format number with Indian commas (e.g., 1,00,000)
    const formattedNumber = new Intl.NumberFormat('en-IN').format(amount);

    // 2. Convert number to Indian words (e.g., One Lakh)
    const words = convert(amount);

    return {
        formattedNumber,
        words
    };
}

// Test cases
const amounts = [1000, 100000, 10000000, 1234567];

amounts.forEach(num => {
    const result = formatIndianCurrency(num);
    console.log(`Number: ${num} -> ${result.formattedNumber} (${result.words})`);
});
```

