const noble = require('@abandonware/noble');

// Battery Service and Characteristic UUIDs
const BATTERY_SERVICE_UUID = '180f';
const BATTERY_LEVEL_CHAR_UUID = '2a19';

noble.on('stateChange', (state) => {
  if (state === 'poweredOn') {
    console.log('Scanning for battery devices...');
    noble.startScanning([BATTERY_SERVICE_UUID], false);
  } else {
    console.log(`Bluetooth state is: ${state}`);
  }
});

noble.on('discover', async (peripheral) => {
  console.log(`Found device: ${peripheral.advertisement.localName} [${peripheral.id}]`);

  noble.stopScanning();

  try {
    await peripheral.connectAsync();
    console.log('Connected!');

    const { characteristics } = await peripheral.discoverSomeServicesAndCharacteristicsAsync(
      [BATTERY_SERVICE_UUID], 
      [BATTERY_LEVEL_CHAR_UUID]
    );

    const batteryChar = characteristics[0][0];
    const data = await batteryChar.readAsync();

    console.log(`Battery Level: ${data[0]}%`);

    await peripheral.disconnectAsync();
    process.exit(0);
  } catch (err) {
    console.error('Error:', err);
    process.exit(1);
  }
});
```

